from pathlib import Path
import json,html
p=Path(__file__).resolve().parents[1];a=json.loads((p/'S50-AUDIT.json').read_text());events=json.loads((p/'S50-EVENTS.json').read_text());out=Path(__file__).resolve().parents[1];data=json.dumps({'summary':a,'events':events},separators=(',',':')).replace('<','\\u003c')
template=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Swarm of Theseus · measured turnover replay</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#101519;color:#e8eeef}body{margin:0 auto;max-width:1160px;padding:30px}h1{font-size:32px;margin:8px 0}p{color:#bac6cd;line-height:1.5}header small{letter-spacing:2px;color:#73d8c3}.controls{display:flex;align-items:center;gap:15px;margin:22px 0}input{flex:1}button{background:#73d8c3;color:#101519;border:0;padding:9px 16px;border-radius:6px}#panels{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.panel{border:1px solid #334249;border-radius:12px;padding:16px;background:#171f24}h2{font-size:18px;margin:0 0 8px}.metrics{display:flex;gap:14px;flex-wrap:wrap;font-size:13px;color:#b7c6ce}.metrics b{font-size:20px;color:#fff}svg{width:100%;max-height:350px}.legend{display:flex;gap:20px;flex-wrap:wrap;font-size:13px;color:#c2cdd1}.key:before{content:'●';color:var(--c);margin-right:5px}.note{background:#1e2a31;padding:14px;border-left:3px solid #73d8c3}.footer{font-size:13px}table{border-collapse:collapse;width:100%;margin:24px 0;font-variant-numeric:tabular-nums}td,th{text-align:left;padding:9px;border-bottom:1px solid #334249}@media(max-width:650px){#panels{grid-template-columns:1fr}body{padding:18px}}
</style><header><small>SOC-24 · OBSERVED NATIVE EVENTS</small><h1>What survives when every founder leaves?</h1><p>One connected institution, fifty active positions, four paired conditions. The arms share one initial ancestor; they are not four independent worlds. This replay uses recorded events, never simulated successes.</p></header><div class="note" id="finding"></div><div class="controls"><button id="play">Play</button><input id="step" aria-label="Completed native request" type="range" min="0" value="0"><output id="counter"></output></div><p id="caption"></p><div class="legend"><span class="key" style="--c:#73d8c3">Observed correct route</span><span class="key" style="--c:#fa887c">Observed wrong route</span><span class="key" style="--c:#65747c">Unobserved</span><span>White outline: observed successor commit</span></div><div id="panels"></div><table id="table"></table><p class="footer">Nodes are organizational positions arranged for display; connecting geometry is not a measured communication graph. Route correctness and decision accuracy are separate. Gray remains missing, and no intermediate behavioral checkpoint is invented. The decision counter uses observed cases; final conclusions use all assigned denominators. One synthetic failover world (n=1), one turnover wave, one model configuration: this cannot establish a population cultural-survival rate or spontaneous culture.</p><script>
const D=__DATA__, arms=['interactive','static','broken','retained'], labels={interactive:'Interactive predecessor handover',static:'Static handover',broken:'Broken inheritance',retained:'Retained founders'}, N=50, max=D.summary.calls;
const slider=document.getElementById('step');slider.max=max;slider.value=max;
const nodes=()=>Array.from({length:N},()=>({known:false,correct:false,g:0}));
function stateAt(step){const st=Object.fromEntries(arms.map(a=>[a,{nodes:nodes(),correct:0,assigned:0,harmful:0,useful:0,replaced:0}]));let last=null;const initial={correct:0,assigned:0};for(const e of D.events){if(e.seq>=step)break;last=e;let at=Number(e.owner.split('_')[1]);if(e.type==='founder'||e.type==='selection'){for(const a of e.arm&&e.arm!=='common'?[e.arm]:arms){st[a].nodes[at].known=true;st[a].nodes[at].correct=e.correct}}else if(e.type==='replacement'){st[e.arm].nodes[at]={known:e.valid,correct:e.correct,g:1};st[e.arm].replaced++}else if(e.type==='decision'){if(e.arm==='common'){initial.correct+=e.correct;initial.assigned+=e.assigned}else{for(const k of ['correct','assigned','harmful','useful'])st[e.arm][k]+=e[k]}}}return{st,last,initial}}
function draw(){const step=Number(slider.value),{st,last,initial}=stateAt(step);document.getElementById('counter').textContent=step+' / '+max+' calls';document.getElementById('caption').textContent=(last?'Latest observed event: '+last.type+' · '+(last.arm||'common')+' · '+last.owner+'. ':'')+'Shared baseline: '+initial.correct+'/'+initial.assigned+' observed correct decisions.';
 document.getElementById('panels').innerHTML=arms.map(a=>{let circles=st[a].nodes.map((n,i)=>{let angle=(i/N)*Math.PI*2-Math.PI/2,x=170+130*Math.cos(angle),y=166+130*Math.sin(angle),color=n.known?(n.correct?'#73d8c3':'#fa887c'):'#65747c';return '<circle cx="'+x+'" cy="'+y+'" r="6" fill="'+color+'" stroke="'+(n.g?'white':'transparent')+'" stroke-width="2"><title>Position '+String(i).padStart(2,'0')+' · '+(n.g?'successor':'founder')+' · '+(n.known?(n.correct?'correct':'wrong'):'unobserved')+' route</title></circle>'}).join('');return '<section class="panel"><h2>'+labels[a]+'</h2><div class="metrics"><span><b>'+st[a].replaced+'</b>/50 successor commits</span><span><b>'+st[a].correct+'</b>/'+st[a].assigned+' observed decisions correct</span><span><b>'+st[a].harmful+'</b> harmful approvals</span></div><svg viewBox="0 0 340 334" role="img" aria-label="Fifty position memory states">'+circles+'<text x="170" y="155" text-anchor="middle" fill="#e8eeef" font-size="27">'+st[a].nodes.filter(n=>n.known&&n.correct).length+'/50</text><text x="170" y="180" text-anchor="middle" fill="#bac6cd" font-size="12">correct observed routes</text></svg></section>'}).join('')}
let timer=null;document.getElementById('play').onclick=()=>{if(timer){clearInterval(timer);timer=null;document.getElementById('play').textContent='Play';return}if(+slider.value>=max)slider.value=0;document.getElementById('play').textContent='Pause';timer=setInterval(()=>{slider.value=Math.min(max,+slider.value+3);draw();if(+slider.value===max){clearInterval(timer);timer=null;document.getElementById('play').textContent='Play'}},90)};slider.oninput=draw;
const summary=D.summary;document.getElementById('finding').textContent=summary.complete?'This native run completed all four conditions. The table shows its observed outcomes; comparisons remain descriptive within one world.':'The native run ended before all conditions completed. The replay shows only observed events; missing endpoints remain unmeasured.';
let table='<tr><th>Condition</th><th>Replacements</th><th>Correct / assigned</th><th>Harmful approvals</th><th>Useful approvals</th></tr>';for(const a of arms){const v=summary.arms?.[a];table+='<tr><td>'+labels[a]+'</td><td>'+(v?v.replacements:'unmeasured')+'</td><td>'+(v?v.terminal.correct+' / '+v.terminal.assigned:'unmeasured')+'</td><td>'+(v?v.terminal.harmful:'unmeasured')+'</td><td>'+(v?v.terminal.useful:'unmeasured')+'</td></tr>'}document.getElementById('table').innerHTML=table;draw();
</script></html>'''
(out/'S50-REPLAY.html').write_text(template.replace('__DATA__',data));print(json.dumps({'html':str(out/'S50-REPLAY.html'),'events':len(events),'native_calls':a['calls']}))
